'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcsLength(a, b) {
  let row = new Array(b.length + 1).fill(0);
  for (const line of a) {
    const next = [0];
    for (let j = 0; j < b.length; j++) {
      next.push(line === b[j] ? row[j] + 1 : Math.max(row[j + 1], next[j]));
    }
    row = next;
  }
  return row[b.length];
}

function sequences(maxLength) {
  const result = [Object.freeze([])];
  let level = [[]];
  for (let length = 1; length <= maxLength; length++) {
    level = level.flatMap(a => ['', 'repeat', '+- '].map(line => Object.freeze([...a, line])));
    result.push(...level);
  }
  return result;
}

test('exhaustive minimality, ordering, and patch roundtrips with repeated lines', () => {
  const inputs = sequences(4);
  for (const a of inputs) for (const b of inputs) {
    const script = diffLines(a, b);
    assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
    assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
    assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcsLength(a, b));
    let inserted = false;
    for (const entry of script) {
      assert.ok(['equal', 'delete', 'insert'].includes(entry.op));
      if (entry.op === 'equal') inserted = false;
      else if (entry.op === 'insert') inserted = true;
      else assert.equal(inserted, false);
    }
    for (const context of [0, 1, 2]) {
      const hunks = unifiedHunks(a, b, { context });
      for (const hunk of hunks) {
        Object.freeze(hunk.lines);
        Object.freeze(hunk);
      }
      Object.freeze(hunks);
      assert.deepEqual(applyHunks(a, hunks), b);
    }
  }
});

test('zero-line coordinates, context clipping, and merge boundary', () => {
  assert.deepEqual(unifiedHunks([], ['+a', ''], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 2, lines: ['++a', '+'] },
  ]);
  assert.deepEqual(unifiedHunks(['-a', ''], [], { context: 0 }), [
    { oldStart: 1, oldLines: 2, newStart: 0, newLines: 0, lines: ['--a', '-'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['top', 'a', 'b', 'end'], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+top'] },
    { oldStart: 2, oldLines: 0, newStart: 4, newLines: 1, lines: ['+end'] },
  ]);
  assert.deepEqual(unifiedHunks(['top', 'a', 'b', 'end'], ['a', 'b'], { context: 0 }), [
    { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-top'] },
    { oldStart: 4, oldLines: 1, newStart: 2, newLines: 0, lines: ['-end'] },
