'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  const trace = [];
  // Each frontier stores the furthest x on each diagonal at edit distance d.
  search: for (let d = 0; d <= a.length + b.length; d++) {
    const frontier = new Int32Array(2 * d + 1);
    const previous = trace[d - 1];
    trace.push(frontier);
    for (let k = -d; k <= d; k += 2) {
      let x;
      if (d === 0) {
        x = 0;
      } else if (k === -d ||
                 (k !== d && previous[k + d - 2] < previous[k + d])) {
        x = previous[k + d];
      } else {
        x = previous[k + d - 2] + 1;
      }
      let y = x - k;
      while (x < a.length && y < b.length && a[x] === b[y]) {
        x++;
        y++;
      }
      frontier[k + d] = x;
      if (x >= a.length && y >= b.length) break search;
    }
  }

  const script = [];
  const deletes = [];
  const inserts = [];
  // Backtracking is reversed: emit inserts first so the final script has
  // all deletes before all inserts within each region without an equal.
  function flushChanges() {
    for (const entry of inserts) script.push(entry);
    for (const entry of deletes) script.push(entry);
    inserts.length = 0;
    deletes.length = 0;
  }

  let x = a.length;
  let y = b.length;
  for (let d = trace.length - 1; d > 0; d--) {
    const k = x - y;
    const previous = trace[d - 1];
    const previousK = k === -d ||
      (k !== d && previous[k + d - 2] < previous[k + d]) ? k + 1 : k - 1;
    const previousX = previous[previousK + d - 1];
    const previousY = previousX - previousK;
    if (x > previousX && y > previousY) flushChanges();
    while (x > previousX && y > previousY) {
      script.push({ op: 'equal', line: a[--x] });
      y--;
    }
    if (x === previousX) {
      inserts.push({ op: 'insert', line: b[--y] });
    } else {
      deletes.push({ op: 'delete', line: a[--x] });
    }
  }
  flushChanges();
  while (x > 0) {
    script.push({ op: 'equal', line: a[--x] });
    y--;
  }
  return script.reverse();
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  if (!Number.isInteger(context) || context < 0) {
    throw new Error('context must be a nonnegative integer');
  }
  const script = diffLines(a, b);
  const hunks = [];
  let cursor = 0;
  let oldPosition = 0;
  let newPosition = 0;
  while (cursor < script.length) {
    while (cursor < script.length && script[cursor].op === 'equal') {
      cursor++;
      oldPosition++;
      newPosition++;
    }
    if (cursor === script.length) break;

    const start = Math.max(0, cursor - context);
    const oldBefore = oldPosition - (cursor - start);
    const newBefore = newPosition - (cursor - start);
    let end = cursor;
    let lastChange = cursor;
    while (end < script.length) {
      if (script[end].op !== 'equal') {
        lastChange = ++end;
      } else {
        const gapStart = end;
        while (end < script.length && script[end].op === 'equal') end++;
        if (end === script.length || end - gapStart > 2 * context) break;
      }
    }
    end = Math.min(script.length, lastChange + context);

    let oldLines = 0;
    let newLines = 0;
    const lines = [];
    for (let i = start; i < end; i++) {
      const { op, line } = script[i];
      if (op !== 'insert') oldLines++;
      if (op !== 'delete') newLines++;
      lines.push((op === 'equal' ? ' ' : op === 'delete' ? '-' : '+') + line);
    }
    hunks.push({
      oldStart: oldBefore + (oldLines === 0 ? 0 : 1),
      oldLines,
      newStart: newBefore + (newLines === 0 ? 0 : 1),
      newLines,
      lines,
    });
    cursor = end;
    oldPosition = oldBefore + oldLines;
    newPosition = newBefore + newLines;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
 * it. Unmentioned original lines are retained. An empty hunk array returns a copy.
 * A mismatch or malformed/nonapplicable hunk throws Error with a message
 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  const result = [];
  let oldPosition = 0;
  function fail(index) {
    throw new Error(`hunk ${index} does not apply`);
  }
  if (!Array.isArray(hunks)) fail(0);
  for (let index = 0; index < hunks.length; index++) {
    const hunk = hunks[index];
    if (hunk === null || typeof hunk !== 'object') fail(index);
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    if (!Number.isSafeInteger(oldStart) || oldStart < (oldLines === 0 ? 0 : 1) ||
        !Number.isSafeInteger(newStart) || newStart < (newLines === 0 ? 0 : 1) ||
        !Number.isSafeInteger(oldLines) || oldLines < 0 ||
        !Number.isSafeInteger(newLines) || newLines < 0 ||
        !Array.isArray(lines)) fail(index);

    const oldIndex = oldStart - (oldLines === 0 ? 0 : 1);
    const newIndex = newStart - (newLines === 0 ? 0 : 1);
    if (oldIndex < oldPosition || oldIndex > a.length ||
        oldLines > a.length - oldIndex ||
        newIndex !== result.length + oldIndex - oldPosition) fail(index);

    while (oldPosition < oldIndex) result.push(a[oldPosition++]);
    let oldCount = 0;
    let newCount = 0;
    for (const entry of lines) {
      if (typeof entry !== 'string' || entry.length === 0) fail(index);
      const prefix = entry[0];
      if (prefix !== ' ' && prefix !== '-' && prefix !== '+') fail(index);
      const line = entry.slice(1);
      if (prefix !== '+') {
        if (oldCount >= oldLines || a[oldPosition] !== line) fail(index);
        oldPosition++;
        oldCount++;
      }
      if (prefix !== '-') {
        if (newCount >= newLines) fail(index);
        result.push(line);
        newCount++;
      }
    }
    if (oldCount !== oldLines || newCount !== newLines) fail(index);
  }
  while (oldPosition < a.length) result.push(a[oldPosition++]);
  return result;
}

module.exports = { diffLines, unifiedHunks, applyHunks };

