'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { performance } = require('node:perf_hooks');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcsLength(a, b) {
  let row = new Array(b.length + 1).fill(0);
  for (const line of a) {
    const next = [0];
    for (let j = 0; j < b.length; j++) {
      next.push(line === b[j] ? row[j] + 1 : Math.max(row[j + 1], next[j]));
    }
    row = next;
  }
  return row[b.length];
}

function sequences(maxLength) {
  const result = [Object.freeze([])];
  let level = [[]];
  for (let length = 1; length <= maxLength; length++) {
    level = level.flatMap(a => ['', 'repeat', '+- '].map(line => Object.freeze([...a, line])));
    result.push(...level);
  }
  return result;
}

test('exhaustive minimality, ordering, and patch roundtrips with repeated lines', () => {
  const inputs = sequences(4);
  for (const a of inputs) for (const b of inputs) {
    const script = diffLines(a, b);
    assert.deepEqual(script.filter(e => e.op !== 'insert').map(e => e.line), a);
    assert.deepEqual(script.filter(e => e.op !== 'delete').map(e => e.line), b);
    assert.equal(script.filter(e => e.op !== 'equal').length, a.length + b.length - 2 * lcsLength(a, b));
    let inserted = false;
    for (const entry of script) {
      assert.ok(['equal', 'delete', 'insert'].includes(entry.op));
      if (entry.op === 'equal') inserted = false;
      else if (entry.op === 'insert') inserted = true;
      else assert.equal(inserted, false);
    }
    for (const context of [0, 1, 2]) {
      const hunks = unifiedHunks(a, b, { context });
      for (const hunk of hunks) {
        Object.freeze(hunk.lines);
        Object.freeze(hunk);
      }
      Object.freeze(hunks);
      assert.deepEqual(applyHunks(a, hunks), b);
    }
  }
});

test('zero-line coordinates, context clipping, and merge boundary', () => {
  assert.deepEqual(unifiedHunks([], ['+a', ''], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 2, lines: ['++a', '+'] },
  ]);
  assert.deepEqual(unifiedHunks(['-a', ''], [], { context: 0 }), [
    { oldStart: 1, oldLines: 2, newStart: 0, newLines: 0, lines: ['--a', '-'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['top', 'a', 'b', 'end'], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['+top'] },
    { oldStart: 2, oldLines: 0, newStart: 4, newLines: 1, lines: ['+end'] },
  ]);
  assert.deepEqual(unifiedHunks(['top', 'a', 'b', 'end'], ['a', 'b'], { context: 0 }), [
    { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['-top'] },
    { oldStart: 4, oldLines: 1, newStart: 2, newLines: 0, lines: ['-end'] },
  ]);
  assert.deepEqual(unifiedHunks(['x', 'a', 'b', 'y'], ['X', 'a', 'b', 'Y'], { context: 1 }), [
    { oldStart: 1, oldLines: 4, newStart: 1, newLines: 4, lines: ['-x', '+X', ' a', ' b', '-y', '+Y'] },
  ]);
  assert.deepEqual(unifiedHunks(['x', 'a', 'b', 'c', 'y'], ['X', 'a', 'b', 'c', 'Y'], { context: 1 }), [
    { oldStart: 1, oldLines: 2, newStart: 1, newLines: 2, lines: ['-x', '+X', ' a'] },
    { oldStart: 4, oldLines: 2, newStart: 4, newLines: 2, lines: [' c', '-y', '+Y'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['a', 'b']), []);
  const a = ['a'];
  assert.deepEqual(applyHunks(a, []), a);
  assert.notEqual(applyHunks(a, []), a);
  const repetitiveA = ['x', 'y', 'x', 'y'];
  const repetitiveB = ['y', 'x', 'y', 'x'];
  assert.deepEqual(diffLines(repetitiveA, repetitiveB), diffLines(repetitiveA, repetitiveB));
});

test('applying external hunks validates original coordinates and all contents', () => {
  const a = Object.freeze(['a', 'b', 'c', 'd', 'e']);
  const hunks = [
    { oldStart: 1, oldLines: 0, newStart: 2, newLines: 2, lines: ['+x', '+y'] },
    { oldStart: 3, oldLines: 1, newStart: 4, newLines: 0, lines: ['-c'] },
    { oldStart: 5, oldLines: 1, newStart: 6, newLines: 2, lines: [' e', '+z'] },
  ];
  assert.deepEqual(applyHunks(a, hunks), ['a', 'x', 'y', 'b', 'd', 'e', 'z']);
  const good = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const bad = [
    null, undefined, {},
    { ...good, oldStart: 0 }, { ...good, newStart: 0 },
    { ...good, oldStart: -1 }, { ...good, oldStart: 1.5 },
    { ...good, newStart: 3 }, { ...good, newStart: NaN },
    { ...good, oldLines: -1 }, { ...good, newLines: -1 },
    { ...good, oldLines: 0 }, { ...good, newLines: 0 },
    { ...good, oldLines: 2 }, { ...good, newLines: 2 },
    { ...good, lines: null }, { ...good, lines: [null] },
    { ...good, lines: [''] }, { ...good, lines: ['?b'] },
    { ...good, lines: ['-wrong', '+B'] }, { ...good, lines: [' wrong'] },
    { ...good, lines: new Array(1) },
    { oldStart: 6, oldLines: 0, newStart: 7, newLines: 1, lines: ['+z'] },
    { oldStart: 5, oldLines: 2, newStart: 5, newLines: 0, lines: ['-e', '-f'] },
  ];
  for (const hunk of bad) assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [good, good]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [hunks[2], good]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [good, { oldStart: 4, oldLines: 1, newStart: 3, newLines: 1, lines: [' d'] }]), /hunk 1 does not apply/);
});

test('20,000-line small changes remain well below one second', () => {
  for (const repetitive of [false, true]) {
    const a = Object.freeze(Array.from({ length: 20000 }, (_, i) => repetitive ? String(i % 3) : `line ${i}`));
    const b = [...a];
    b.splice(19990, 1);
    b.splice(10000, 1, 'replacement');
    b.splice(2, 0, 'inserted');
    Object.freeze(b);
    const start = performance.now();
    const script = diffLines(a, b);
    const hunks = unifiedHunks(a, b);
    const applied = applyHunks(a, hunks);
    const elapsed = performance.now() - start;
    assert.deepEqual(applied, b);
    assert.equal(script.filter(e => e.op !== 'equal').length, 4);
    assert.ok(elapsed < 500, `${elapsed}ms`);
    console.log(`20,000 lines (${repetitive ? 'repetitive' : 'unique'}): ${elapsed.toFixed(2)}ms`);
    assert.deepEqual(unifiedHunks(a, a), []);
  }
});

